// One card, face or back, at the small or large size (epic 3, R6, R7;
// DESIGN.md, Card face, Card back, Rarity seal, Dust). The twin of
// CardComponent (app/components/card_component.html.erb): same element tree,
// same classes, same stylesheet (styles/card.css) and pixel parts
// (images/card/, generated by script/card_art/generate.mjs). Imported by the
// reveal (story 3.6); not an island of its own.
import { useEffect, useRef } from "react"
import { CARD_ART, drawCardArt, type CardSize } from "../lib/card_art"
import spriteUrl from "../images/card/sprite.svg"

export type Rarity = "steel" | "emerald" | "sapphire" | "amethyst" | "gold"

/** Catalog::CardView#to_props. */
export type CardView = {
  id: string
  title: string
  publisher: string | null
  year: number
  seasonNumber: number
  rarity: Rarity
  dust: number
  imageUrl: string
}

/** CardStrings#to_props: every word resolved on the server. */
export type CardStrings = {
  rarityNames: Record<Rarity, string>
  faceDown: string
  faceDownByRarity: Record<Rarity, string>
  /** "Season n", keyed by the season number. */
  seasons: Record<string, string>
}

export type CardSide = "face" | "back"

export type CardProps = {
  card: CardView
  size: CardSize
  side: CardSide
  strings: CardStrings
  /** On a back: whether the label names the rarity (the seal can be seen). */
  sealVisible?: boolean
}

const SPARKLES = 7
const WIDE_SEASON = 10

const sprite = (symbol: string) => `${spriteUrl}#${symbol}`

function Glyphs({ text }: { text: string }) {
  return (
    <span className="card__marks" aria-hidden="true">
      {[...text.toUpperCase()].map((glyph, index) => (
        <svg className="card__glyph" key={index}>
          <use href={sprite(`glyph-${glyph}`)} />
        </svg>
      ))}
    </span>
  )
}

function Art({ url, size }: { url: string; size: CardSize }) {
  const container = useRef<HTMLSpanElement>(null)
  const canvas = useRef<HTMLCanvasElement>(null)
  const { width, height } = CARD_ART[size]

  useEffect(() => {
    if (!container.current || !canvas.current) return
    const abort = new AbortController()
    void drawCardArt(container.current, canvas.current, url, { width, height, signal: abort.signal })
    return () => abort.abort()
  }, [url, width, height])

  return (
    <span className="card__art" ref={container}>
      <canvas className="card__canvas" width={width} height={height} aria-hidden="true" ref={canvas} />
    </span>
  )
}

export default function Card({ card, size, side, strings, sealVisible = true }: CardProps) {
  const classes = `card card--${size} card--${side} card--rarity-${card.rarity} card--dust-${card.dust}`

  if (side === "back") {
    return (
      <span className={classes} role="img" aria-label={sealVisible ? strings.faceDownByRarity[card.rarity] : strings.faceDown}>
        <svg className="card__seal" aria-hidden="true">
          <use href={sprite(`seal-${card.rarity}`)} />
        </svg>
        {card.dust > 0 && <span className="card__dust" aria-hidden="true" />}
      </span>
    )
  }

  const season = strings.seasons[String(card.seasonNumber)]
  // As CardStrings#season on the server: a season without its string is a bug.
  if (season === undefined) throw new Error(`No string for season ${card.seasonNumber}`)
  const wide = card.seasonNumber >= WIDE_SEASON
  const seasonSeal = wide ? "season-seal-wide" : "season-seal"

  return (
    <span className={classes}>
      <span className="card__frame" aria-hidden="true" />
      <span className="card__piping" aria-hidden="true" />
      <span className="card__window">
        <Art url={card.imageUrl} size={size} />
        <span className="card__year">
          <Glyphs text={String(card.year)} />
          <span className="visually-hidden">{card.year}</span>
        </span>
        <span className="card__plate">
          <span className="card__title">{card.title}</span>
          {size === "large" && card.publisher && <span className="card__publisher">© {card.publisher}</span>}
          <span className="visually-hidden">{strings.rarityNames[card.rarity]}</span>
          <span className={wide ? "card__season card__season--wide" : "card__season"}>
            <svg className="card__season-seal" aria-hidden="true">
              <use href={sprite(seasonSeal)} />
            </svg>
            <Glyphs text={`S${card.seasonNumber}`} />
            <span className="visually-hidden">{season}</span>
          </span>
        </span>
      </span>
      {card.rarity === "gold" && (
        <span className="card__shine" aria-hidden="true">
          <span className="card__sweep" />
          {Array.from({ length: SPARKLES }, (_, index) => (
            <span className="card__sparkle" key={index} />
          ))}
        </span>
      )}
    </span>
  )
}
